def bell_Number(n):
    if n == 0:
        return 1

    # Initialize Bell triangle (first row)
    bell = [[0] * (n + 2) for _ in range(n + 2)]

    # First element of the first row is always 1
    bell[0][1] = 1

    # Build the Bell triangle
    for i in range(1, n + 1):
        # The first element of each new row is the last element of the previous row
        if i < len(bell) - 1:
            bell[i][i+1] = bell[i-1][-1]

        # Fill the rest of the current row using values from the left and above-left neighbors
        for j in range(i + 2, n + 3):
            if i < len(bell) - 1:
                bell[i][j] = bell[i-1][j-1] + bell[i][j-1]

    # The nth Bell number is the last element of the (n-1)-th row in our triangle structure
    return bell[n-1][-2] if n > 0 else 1

